#include <bits/stdc++.h>
using namespace std;

int dfs(int cur,vector<int> a){

	if(cur==-1)return 0;
	vector<int> S,T;

	for(int i=0;i<a.size();i++){
		if(((a[i]>>cur)&1)==0)S.push_back(a[i]);
		else T.push_back(a[i]);
	}

	if(S.size()==0)return dfs(cur-1,T);
	if(T.size()==0)return dfs(cur-1,S);
	return min(dfs(cur-1,S),dfs(cur-1,T)) | (1<<cur);

}

int main() {

	int N;
	cin>>N;

	vector<int> a(N);
	for(int i=0;i<N;i++)cin>>a[i];

	cout<<dfs(29,a)<<endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for(auto &v : a) cin >> v;
    sort(a.begin(), a.end());
    auto f = [&](auto f, int l, int r, int d = 30) -> int {
        if(d == -1) return 0;
        if((a[l] ^ a[r - 1]) >> d & 1) {
            int m = distance(a.begin(), lower_bound(a.begin() + l, a.begin() + r, a[r - 1] >> d << d));
            return min(f(f, l, m, d - 1), f(f, m, r, d - 1)) + (1 << d);
        } else
            return f(f, l, r, d - 1);
    };
    cout << f(f, 0, n) << endl;
}
